{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Naloxone itself is described as having poor oral bioavailability, directly indicating F < 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Naltrexone, the closest structural analogue (N-cyclopropylmethyl instead of N-allyl), has ~5% oral bioavailability in healthy volunteers due to extensive first-pass hepatic metabolism; the query's N-allyl naloxone is expected to undergo similarly or more extensive first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Naltrexone has very poor oral bioavailability of about 5-10%, reinforcing the low-F pattern for this 4,5-epoxymorphinan scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Butorphanol, another opioid agonist-antagonist with a similar phenolic morphinan core, has absolute oral bioavailability of only 5-17%, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nalmefene, a 6-methylene naltrexone analogue, has absolute oral bioavailability of 41%, showing that structural modification can raise F; however, the query lacks this modification and this evidence is less transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is naloxone. Direct evidence describes naloxone as having poor oral bioavailability, and the closest analogue naltrexone shows low F (5-10%) due to extensive first-pass metabolism. High-F analogues such as nalmefene, naloxegol, and samidorphan are structurally modified to improve oral bioavailability and are less transferable to the unmodified naloxone scaffold. Therefore, F is predicted to be below 20% (low).",
  "evidence_gaps": [
    "No quantitative absolute oral bioavailability value for naloxone is provided in the evidence; only qualitative 'poor' is reported.",
    "Naltrexone records are mixed (5-60%), though most support low oral bioavailability.",
    "High-F analogues are structurally modified and may not transfer to the unmodified naloxone query."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C23"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "opioid antagonist/morphinan"
    }
  ],
  "revision_action": "initial"
}

